  const findAnchor = (id) => document.getElementById(id)
    || Array.from(document.getElementsByName(id))[0]
    || null;

  document.addEventListener('click', (event) => {
    const target = event.target && event.target.nodeType === 1
      ? event.target
      : event.target && event.target.parentElement;
    const link = target && target.closest ? target.closest('a[href]') : null;
    if (!link) return;

    const href = String(link.getAttribute('href') || '').trim();
    if (!href || href.startsWith('javascript:')) return;
    if (href.startsWith('#axhub-target:')) {
      event.preventDefault();
      post('target', href);
      return;
    }
    if (href.startsWith('#')) {
      const anchorId = decodeHash(href);
      if (anchorId && findAnchor(anchorId)) {
        event.preventDefault();
        post('hash', href, anchorId);
      }
      return;
    }
    if (!isExternal(href) && isDocumentPath(href)) {
      event.preventDefault();
      post('internal', href);
    }
  }, true);

